export default function formatDate(date,format){
    let d = date;
    let year = d.getFullYear();
    let month = d.getMonth() + 1;
    let day = d.getDate();
    let str = format.replaceAll('yyyy',year)
                    .replaceAll('MM',month < 10 ? '0' + month : month)
                    .replaceAll('dd',day < 10 ? '0' + day : day)
                    .replaceAll('HH',d.getHours().toString().padStart(2,'0'))
                    .replaceAll('mm',d.getMinutes().toString().padStart(2,'0'))
                    .replaceAll('ss',d.getSeconds().toString().padStart(2,'0'))
                    .replaceAll('day',`星期${d.getDay()}`);
    
    return str;
}