<template>
    <div class="mainNav-container">
        <LeftNav :gap="leftNavGap"></LeftNav>
        <div class="form-item">
            <div class="inner">
                <div class="wrapper-detail">
                    <input type="text" placeholder="搜索">
                    <Icons type="search" class="icon" color="#000000ea"></Icons>
                </div>
            </div>
        </div>
        <rightNav :gap="rightNavGap" :isShowTitle="isShowTitle"></rightNav>
    </div>
</template>

<script>
import LeftNav from '@/components/Nav/LeftNav.vue';
import RightNav from '@/components/Nav/RightNav.vue';
import Icons from '@/components/Icons.vue';
export default {
    components: {
        LeftNav,
        RightNav,
        Icons,
    },
    props: {
        fontColor: {
            type: String,
            default: "white"
        }
    },
    created() {

    },
    mounted() {
        this.handleResize(window.innerWidth);
        this.$bus.$on('resize', this.handleResize);
    },
    beforeDestroy() {
        this.$bus.$off('resize', this.handleResize);
    },
    data() {
        return {
            leftNavGap: 15,
            rightNavGap: 20,
            isShowTitle: true,
        }
    },
    methods: {
        // 处理窗口大小变化
        // 当窗口宽度小于1270px，左导航栏间距为7px，右导航栏间距为10px，标题是否显示为false
        // 当窗口宽度大于等于1270px，左导航栏间距为15px，右导航栏间距为20px，标题是否显示为true
        handleResize(w) {
            // console.log("top",w);
            this.leftNavGap = parseInt(w) < 1270 ? 7 : 15;
            this.isShowTitle = parseInt(w) < 1270 ? false : true;
            this.rightNavGap = parseInt(w) < 1270 ? 10 : 20;
        }
    }
}
</script>

<style lang="less" scoped>
@inputWidth: 100%;
@navHeight: 66px;
@borderRadius: 7px;

.mainNav-container {
    display: flex;
    align-items: center;
    background-color: var(--bg_color);
    box-sizing: border-box;
    padding: 0 24px;
    height: @navHeight;
    position: absolute;
    z-index: 100;
    width: 100%;
    background-color: transparent;

    .form-item {
        flex: 1 auto;
        margin: 0 auto;

        .inner {
            margin: 0 auto;
            min-width: 188px;
            max-width: 500px;
            position: relative;
            border-radius: @borderRadius;
            height: calc(@navHeight / 2);

            &:hover {
                background-color: white;
            }

            .wrapper-detail {
                background-color: rgba(255, 255, 255, 0.705);
                position: relative;
                height: 100%;
                box-sizing: border-box;
                padding: 0 7px;
                padding-top: 3px;
                padding-bottom: 2px;
                display: flex;
                justify-content: center;
                border-radius: inherit;

                input {
                    width: 100%;
                    height: 100%;
                    border-radius: @borderRadius;
                    background-color: transparent;
                    padding: 0;
                    padding-left: 3px;
                    flex: 1 auto;

                    &:focus {
                        background-color: #E3E5E7;
                    }
                }

                .icon {
                    @offset: 5px;
                    @size: calc(@navHeight / 2 - @offset);
                    cursor: pointer;
                    display: block;
                    width: @size;
                    height: @size;
                    border-radius: 4px;
                    margin-left: @offset;

                    &:hover {
                        background-color: rgba(128, 128, 128, 0.61);
                    }
                }
            }

        }
    }
}
</style>