import request from '@/utils/request'

export function getBanner() {
    return request.get('/api/banner', 'get')
}

export function getVideoList( page = 1, limit = 10 ) {
    return request.get('/api/videoList', {
        params: {
            page,
            limit,
        }
    })
}

export function getSpecialVideoList( page = 1, limit = 3 ) {
    return request.get('/api/specialVideo', {
        params: {
            page,
            limit,
        }
    })
}

export function getHeadVideoList( page = 1, limit = 10 ) {
    return request.get('/api/headVideoList', {
        params: {
            page,
            limit,
        }
    })
}

export function getDynamicPop() {
    return request.get('/api/dynamicPop', 'get')
}