<template>
    <div class="RightNav-container">
        <div class="avtar">
            <MyImage :src="userAvatar" :width="40" :height="40"></MyImage>
        </div>
        <ul :style="{ gap: gap + 'px' }">
            <li v-for="(item, i) in computedNavList" :key="i">
                <router-link :to="{
                    name: item.name,
                }">
                    <MySlot v-if="item.hasPop">
                        <template #trigger>
                            <Icons :type="item.icon" :title="isShowTitle ? item.title : ''" :size="iconSize" :hasAnimation="item.isAnimation" :color="iconColor"></Icons>
                        </template>
                        <template #hoverContainer="{isHover, setLeftOffset}">
                            <component :is="item.component" :isHover="isHover" :setLeftOffset="setLeftOffset"></component>
                        </template>
                    </MySlot>
                    <Icons v-else :type="item.icon" :title="isShowTitle ? item.title : ''" :size="iconSize" :hasAnimation="item.isAnimation" :color="iconColor">
                    </Icons>
                </router-link>
            </li>
        </ul>
        <div class="pushBlog">
            <Icons type="pushBlog" :size="iconSize" :title="isShowTitle ? '投稿' : ''" direction="row"></Icons>
        </div>
    </div>
</template>

<script>
import Icons from "@/components/Icons.vue";
import MyImage from "@/components/MyImage.vue";
import avatar from "@/assets/avatar.avif";
import rightNavConfig from "@/config/rightNavConfig.js";
import MySlot from "@/components/MySlot.vue";
export default {
    name: "RightNavComponent",
    components: {
        Icons,
        MyImage,
        MySlot
    },
    props: {
        gap: {
            type: Number,
            default: 20
        },
        isShowTitle: {
            type: Boolean,
            default: true
        },
        iconSize: {
            type: Number,
            default: 22
        }
    },
    data() {
        return {
            navList: [
                {
                    type: "bigVip",
                    title: "大会员",
                    size: 22
                },
                {
                    type: "email",
                    title: "消息",
                    size: 22
                },
                {
                    type: "dynamic",
                    title: "动态",
                    size: 22
                },
                {
                    type: "collect",
                    title: "收藏",
                    size: 22
                },
                {
                    type: "history",
                    title: "历史记录",
                    size: 22
                },
                {
                    type: "editCenter",
                    title: "创作中心",
                    size: 22
                }
            ],
            userAvatar: avatar,
            
        }
    },
    created() {
        // 获取全局颜色
        this.iconColor = document.documentElement.style.getPropertyValue('--icon_color');
    },
    computed: {
        computedNavList() {
            return rightNavConfig;
        }
    }
}
</script>

<style lang="less" scoped>
.RightNav-container {
    display: flex;
    align-items: center;
    color: var(--icon_word);
    height: 100%;

    .avtar {
        width: 40px;
        height: 40px;
        margin: 0 10px;
        border-radius: 50%;
        overflow: hidden;
    }

    ul {
        display: flex;
        align-items: center;
        justify-content: center;
        height: 100%;
        li {
            display: flex;
            align-items: center;
            justify-content: center;
            height: 100%;
            font-size: 14px;
            a{
                display: flex;
                align-items: center;
                height: 100%;
            }
        }
    }

    .pushBlog {
        display: flex;
        align-items: center;
        justify-content: center;
        background-color: #fb7299;
        margin-left: 15px;
        box-sizing: border-box;
        padding: 2px 15px;
        border-radius: 7px;
        height: 34px;
        font-size: 14px;
        cursor: pointer;
        letter-spacing: 2px;
    }
}
</style>