<template>
    <div class="slot-container" @mouseenter="handleMouseEnter" @mouseleave="handleMouseLeave">
        <slot name="trigger" class="trigger"></slot> 
        <div v-show="showPop" class="hoverPop" :style="{ left: leftOffset }">
            <slot name="hoverContainer" :isHover="showPop" :loaded="loaded" :setLeftOffset="setLeftOffset"></slot>
        </div>           
    </div>
</template>

<script>
    export default {
        name:"MySlotHover",
        data(){
            return {
                showPop: false,
                loaded: true, // 是否是第一次加载,是的话表示true，不是的话表示false
                count: 0, // 
                leftOffset: '0' // 初始值，由子组件控制
            }
        },
        methods:{
            handleMouseEnter(){
                
                this.showPop = true;
                if(this.count >= 1){
                    this.loaded = false;
                    return
                }
                this.loaded = true;
                this.count++;
            },
            handleMouseLeave(){
                this.showPop = false;

            },
            setLeftOffset(value){
                this.leftOffset = value;
            }
        }
    }
</script>

<style lang="less" scoped>
.slot-container{
    position: relative;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
}
// .slot-container:hover .hoverPop{
//     display: block;
// }
.hoverPop{
    position: absolute;
    top: 100%;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: #e19595;
    border-radius: 5px;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
    // display: none;
}
.hoverContainer{
    width: 100%;
    height: 100%;
}

</style>