import { getDynamicPop } from '@/api/home'

export default {
    namespaced: true,
    state: {
        hasFetched: true, // 是第一次请求吗。如果是第一次请求，需要请求接口，isOnced 为 true.如果不是则就不需要请求接口
        // 动态弹窗数据
        dynamicList: [],
        loading: false, // 加载中.
    },
    mutations: {
        setDynamicPop(state, data) {
            // state.dynamicList = [...state.dynamicList, ...data]
            state.dynamicList = data
        },
        setLoading(state, loading) {
            state.loading = loading
        }
    },
    actions: {
        async getDynamicPop({ commit, state }) {           
            if (!state.hasFetched) return
            state.hasFetched = false
            commit('setLoading', true)
            console.log("request dynamic pop");
            const res = await getDynamicPop()
            commit('setDynamicPop', res)
            console.log(res);
            commit('setLoading', false) 
            // state.isOnced = false
        }
    }
}