<template>
    <div class="dynamicPop">
        <h1 class="title1">动态</h1>
        <div class="line"><span class="title2">历史动态</span></div>
        <div v-if="loading" class="loading">
            加载中...
        </div>
        <div v-else class="dynamicList">
            <div v-for="item in dynamicList" :key="item.id" class="dynamicItem">
                <div class="avatar">
                    <img :src="item.avatar" :alt="item.anchorName">
                </div>
                <div class="info">
                    <div class="name">{{ item.anchorName }}</div>
                    <div class="description">{{ item.description }}</div>
                    <div class="time">{{ formatDate(new
                        Date(parseInt(item.createDate)), "MM-dd") }}</div>
                </div>
                <div class="img">
                    <img :src="item.image" :alt="item.anchorName">
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import { mapState } from 'vuex'
import formatDate from '@/utils/formatDate'
export default {
    name: "dynamicPop",
    props: {
        isHover: {
            type: Boolean,
            default: false
        },
        setLeftOffset: {
            type: Function,
            default: () => { }
        }
    },
    computed: {
        ...mapState('dynamicPop', ['dynamicList', 'loading']),
    },
    watch: {
        isHover(val) {
            if (val) {
                this.$store.dispatch("dynamicPop/getDynamicPop");
            }
        }
    },
    created() {
        console.log(this.$store.state.dynamicPop);
        console.log(this.dynamicList);
        // 在这里设置 hoverPop 的 left 值
        this.setLeftOffset('-200px');
    },
    methods: {
        formatDate
    }
}
</script>

<style lang="less" scoped>
.dynamicPop {
    width: 400px;
    height: 500px;
    background-color: #ffffff;
    border-radius: 5px;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
    overflow-y: auto;
    overflow-x: hidden;
    left: -50%;
    box-sizing: border-box;
    padding: 20px;
    color: #000;

    h1 {
        font-weight: bold;
        font-size: 20px;
        color: #000;
        padding: 10px 0;
        margin-bottom: 10px;
    }

    .line {
        font-size: 12px;
        color: rgb(148, 146, 146);
        text-align: center;
        box-sizing: border-box;
        padding: 0 30px;
        height: 0;
        border: .1px solid rgb(180, 178, 178);
        position: relative;

        span {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background-color: white;
        }
    }

    .dynamicList {
        margin-top: 10px;
        display: flex;
        justify-content: space-between;
        align-items: center;
        flex-direction: column;
        width: 100%;

        .dynamicItem {
            display: flex;
            justify-content: space-between;
            align-items: center;
            width: 100%;
            height: 110px;

            .avatar {
                width: 15%;
                height: 100%;
                display: flex;
                justify-content: center;
                align-items: center;

                img {
                    width: 70%;
                    border-radius: 50%;
                }
            }

            .info {
                display: flex;
                flex: 1 auto;
                flex-direction: column;
                // justify-content: center;
                // align-items: center;
                gap: 5px;
                box-sizing: border-box;
                padding: 0 5px;
                
                .name{
                    font-size: 14px;
                    color: lightgray;
                }
            }

            .img {
                width: 20%;
                height: 100%;
                display: flex;
                justify-content: center;
                align-items: center;

                img {
                    height: 50%;
                }
            }
        }
    }

}
</style>