<template>
    <div class="LeftNav-container">
        <ul class="" :style="{ gap: gap + 'px' }">
            <li v-for="(item, i) in computedNavList" :key="i" class="item" :class="{ hasAnimation: item.isAnimation }">
                <router-link :to="{
                    name: item.name,
                    query: {
                        id: item.id
                    }
                }">
                    <Icons v-if="item.icon === 'none' ? false : true" :type="item.icon" :size="item.size" :color="iconColor"></Icons>
                    <MySlotHover v-if="item.hasPop">
                        <template #trigger>
                            <span>{{ item.title }}</span>
                        </template>
                        <template #hoverContainer>
                            <component :is="item.component" />
                        </template>
                    </MySlotHover>
                    <span v-else>{{ item.title }}</span>
                </router-link>
            </li>
        </ul>
    </div>
</template>

<script>
import Icons from '@/components/Icons.vue';
import MySlotHover from '@/components/MySlot.vue';
import navList from '@/config/leftNavConfig.js'
export default {
    components: {
        Icons,
        MySlotHover,
    },
    props: {
        gap: {
            type: Number,
            default: 15
        },
    },
    created() {
        // console.log(this.$router.options.routes);
        // 获取全局颜色
        this.iconColor = document.documentElement.style.getPropertyValue('--icon_color');
    },

    data() {
        return {

        }
    },
    computed: {
        computedNavList() {
            return navList;
        }
    },
    methods: {

    }
}
</script>

<style lang="less" scoped>
@import '~@/styles/common.less';

.hasAnimation:hover {
    animation: animation_jump 0.2s ease-in-out;
}

.LeftNav-container {
    height: 100%;
    background-color: transparent;
    box-sizing: border-box;
    padding: 0 24px;
    padding-left: 0;
}

ul {
    height: 100%;
    display: flex;
    color: var(--word_color);
    font-size: 14px;

    .item {
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 10px 0;
        cursor: pointer;

        a {
            display: flex;
            align-items: center;
            height: 100%;
            white-space: nowrap;
        }
    }
}
</style>