<template>
    <div class="Icons-container" :style="{flexDirection: direction}">
        <i class="iconfont myIcon" :class="{
            [mapIcons]: true,
            hasAnimation: hasAnimation,
        }" :style="{fontSize: size + 'px',color: color}" ></i>
        <span v-if="title">{{title}}</span>
    </div>
</template>

<script>

let classMap = {
    email:"icon-youxiang",
    bigVip:"icon-dahuiyuanx",
    history:"icon-lishijilu",
    history1:"icon-lishi2",
    dynamic:"icon-dongtai",
    activity:"icon-huodong",
    community:"icon-nav_shequzhongxin",
    teaching:"icon-a-040_falvketang",
    musiccenter:"icon-gequ",
    collect:"icon-shoucang",
    blackboard:"icon-zhuanlan1",
    logo:"icon-bilibili-line",
    loadFailed:"icon-jiazaishibai",
    download:"icon-xiazai",
    editCenter:"icon-xingzhuang",
    pushBlog:"icon-zhenggaotougao",
    search:"icon-search",
    left:"icon-left",
    right:"icon-right",
    fire:"icon-douyinxiaohuohua",
    live:"icon-yunzhibo",
    views:"icon-shipin",
    danmu:"icon-danmushu"
   };
    export default {
        name: "IconsComponent",
        props: {
            type: {
                type: String,
                required: true
            },
            size:{
                type: Number,
                default: 24
            },
            color:{
                type: String,
                default: "#fff"
            },
            title:{
                type: String,
                default: ""
            },
            direction:{
                type: String,
                default: "column"
            },
            hasAnimation:{
                type: Boolean,
                default: false
            }
        },
        computed:{
            mapIcons(){
                return classMap[this.type] || "icon-jiazaishibai"
            }
        }
    }
</script>

<style lang="less" scoped>
@import "//at.alicdn.com/t/c/font_5161828_fbbjgfpdd3.css";
@import "~@/styles/common.less";

.hasAnimation:hover{
    animation: animation_jump 0.3s ease-in-out;
}
.Icons-container{
    display: flex;
    gap:2.5px;
    align-items: center;
    justify-content: center;
    
}
</style>