import Mock from 'mockjs'

Mock.mock('/api/banner', "get", {
    "code": 0,
    "msg": "",
    "data|7": [
        {
            "id": "@guid",
            "image": function () {
                return "https://picsum.photos/500/300?random=" + Math.random()
            },
            "description": "@csentence(5,10)",
            "background":"@color",
            
        }
    ]
})

Mock.mock(/\/api\/videoList/, "get", (rep) => {
    const url = new URL(rep.url,"https://localhost")
    const page = parseInt(url.searchParams.get("page") || 1);
    const limit = parseInt(url.searchParams.get("limit") || 10);
    const total = 150;
    const list = Mock.mock({
        [`data|${total}`]:[
            {
                "id": "@guid",
                "title": "@csentence(4,20)",
                "img": function () {
                    return "https://picsum.photos/250/144?random=" + Math.random()
                },
                "author": "@word(1,6)",
                "likes": "@integer(0,20000)",
                "views": "@integer(0,100000)",
                "comments": "@integer(0,10000)",
                "duration": "@integer(1,5000)",
                // 返回一个时间戳
                createDate: "@date('T')",
                "isFollow|1":["已关注","未关注",""],
                "type":"normal",
            }
        ]
    }).data;
    const start = (page - 1) * limit;
    const end = start + limit;
    const pageList = list.slice(start, end);
    return {
        code: 0,
        msg: "",
        data: pageList,
        total,
        page,
        limit,
    }
})

