    </ul>
    <div class="right">
        <div v-for="item in sideNav" :key="item.name" class="item">
            <Icons :type="item.icon" color="black" :size="item.size"></Icons>
            <router-link :to="item.name">{{item.title}}</router-link>
        </div>
    </div>
    </div>
    </div>
</template>

<script>
import secondNavConfig from "@/config/secondNavConfig.js"
import Icons from "@/components/Icons.vue"
import sideNav from "@/config/sideNav.js"

export default {
    name: "SecondNav",
    components: {
        Icons
    },
    data() {
        return {
            avatar: "",
            secondNavConfig,
            sideNav,
            maxItems: 21,
            hideItemsArr: []
        }
    },
    created() {
        console.log(this.viewItems, this.hideItems);
    },
    mounted() {
        this.handleResize(window.innerWidth)
        this.$bus.$on("resize", this.handleResize)
    },
    beforeDestroy() {
        this.$bus.$off("resize", this.handleResize)
    },
    computed: {
        viewItems() {
            const viewItems = this.secondNavConfig.filter(item => item.order <= this.maxItems && !this.hideItemsArr.includes(item.title))
            return viewItems
        },
        hideItems() {
            const hideItems = this.secondNavConfig.filter(item => item.order > this.maxItems || this.hideItemsArr.includes(item.title))
            return hideItems
        },

    },
    methods: {
        handleResize(w) {
            this.maxItems = 21;
            this.hideItemsArr = [];
            this.$refs.secondNav.style.setProperty('--cols', 11)
            if (parseInt(w) <= 1366) {
                this.maxItems = 19;
                this.hideItemsArr = ['电影', '运动', '时尚', '动物']
                this.$refs.secondNav.style.setProperty('--cols', 9)
            }
        }
    }
}
</script>

<style lang="less" scoped>
.second-nav {
    width: 85%;
    height: 110px;
    display: flex;
    margin: 0 auto;
    --gap: 15px;
    --cols: 11;
    @media screen and (max-width: 1605px) {
        width: 90%;
        
    }
    @media screen and (max-width: 1444px) {
        width: 93%;
        
    }
    @media screen and (max-width: 1366px) {
        width: 95%;
    }
    .inner {
        width: 100%;
        height: 100%;
        display: flex;
        align-items: center;
        column-gap: 10px;

        .left {
            display: flex;
            justify-content: center;
            align-items: center;
            width: 12%;
            column-gap: 15px;

            @media screen and (max-width: 1366px) {
                column-gap: 7px;
            }

            .item {
                display: flex;
                justify-content: center;
                align-items: center;
                flex-direction: column;
                font-size: 14px;
                gap: 3px;

                .inner {
                    width: 46px;
                    height: 46px;
                    border-radius: 50%;
                    background-color: var(--fire_bg_color);
                    display: flex;
                    justify-content: center;
                    align-items: center;
                }
            }
        }

        .nav-list {
            flex: 1 auto;
            display: grid;
            grid-template-columns: repeat(var(--cols), 1fr);
            grid-template-rows: repeat(2, 1fr);
            grid-gap: var(--gap);
            margin-right: 25px;

            .more {
                position: relative;
                --li_width: calc((100% - (var(--gap) * (var(--cols) - 1))) / var(--cols));
                --pop_width: 400px;
                display: block;
                background-color: var(--item_bg_color);
                border-radius: 6px;
                display: flex;
                justify-content: center;
                align-items: center;
                letter-spacing: 2px;
                transition: all .3s ease-in-out;
                padding: 3px 1.5px;
                &:hover .pop {
                    opacity: 1;
                    visibility: visible;
                    transform: translate(0, 0px);
                }
                .pop {
                    position: absolute;
                    top: 100%;
                    right: 0;
                    width: var(--pop_width);
                    height: 180px;
                    border-radius: 7px;
                    padding-top: 7px;
                    opacity: 0;
                    visibility: hidden;
                    transform: translate(0, -10px);
                    transition: all .2s ease-in-out;
                    z-index: 100;
                    .inner {
                        width: 100%;
                        height: 100%;
                        background-color: cornflowerblue;
                        display: grid;
                        grid-template-columns: repeat(5, 1fr);
                        grid-gap: 10px;
                        padding: 20px;
                        box-sizing: border-box;
                        border-radius: inherit;
                        align-items: start;
                    }
                }
            }

            >li {
                width: 100%;
                height: 100%;
                color: var(--item_word_color);
                font-size: 14px;

                a {
                    display: block;
                    background-color: var(--item_bg_color);
                    padding: 3px;
                    height: 100%;
                    border-radius: 6px;
                    display: flex;
                    justify-content: center;
                    align-items: center;
                    letter-spacing: 2px;
                    transition: all .3s ease-in-out;

                    &:hover {
                        background-color: var(--item_bg_color_hover);
                        color: var(--item_word_color_hover);
                    }
                }
            }

