<template>
    <div>
        <img :src="computedUrl" :width="width" :height="height" :object-fit="fit" alt="">
    </div>
</template>

<script>

    export default {
        props:{
            src:{
                type: String,
                default: ""
            },
            width:{
                type: Number,
                default: 100
            },
            height:{
                type: Number,
                default: 100
            },
            fit:{
                type: String,
                default: "none"
            }
        },
        computed: {
            computedUrl(){
                // 检测一下是否带有协议
                if(!/^https?:\/\//.test(this.src)){
                    return this.src
                }else{
                    return ""
                }
            }
        },
    }
</script>

<style lang="less" scoped>
img{
    width: 100%;
    height: 100%;
}
</style>